namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokPorovnaniRezervaceSmlouvyTab extends GContentBase {
      
        private grid: JQuery;  
        public ixp: string;
        public radek: number;

        onContentReady() {

            var that = this;

            this.title = 'Porovnání FP pol SML rez. pol POK';           


            this.grid = $("<div>").appendTo(this.element).gautofit()
                .ggrid({
                    columnMode: "fit",
                    columns: this.createGridFormat()
                });


            that.NactiData();

        }

        private NactiData(): void {


            let that = this;

            that.beginOperation("Probíhá načtení rezervačních zápisů");

                                    that.call("RezervacniZapisy", { ixp: that.ixp, radek: that.radek })
                                        .done(function (row: GPokPorovnaniRezervaceDto[]) {

                                      


                                            var view = new Gordic.Data.View(row);
                                                that.grid.ggrid("setData", view);
                                                that.endOperation();

                                         
                                                

                                        }) //end call
                                        .always(function () {

                                            that.endOperation();
                                        })




        }


        private createGridFormat(): Gordic.Data.GridFormat<Gordic.Fuc.Interface.GPohybDto> {
            var gridFormat = new Gordic.Data.GridFormat<Gordic.Fuc.Interface.GPohybDto>();

            gridFormat.addTextColumn({ name: "popis", caption: "" });
            gridFormat.addTextColumn({ name: "id", caption: "" });
            gridFormat.addSortedEkoCfuSet(this, true);
            gridFormat.addTextColumn({ name: "nks", caption: "NKS" });
            gridFormat.addCurrencyColumn({ name: "c", caption: "Částka pol./zbývá SML" });


            return gridFormat;

        }
    }
        }

    
